}

scheme.model_answer:
```cpp
#include <iostream>
using namespace std;
int main() {
    int a[6] = {7, 4, -3, 10, 5, 2};
    int S = 0, K = 0;
    for (int i = 0; i < 6; i++) {
        if (a[i] % 2 == 0) S = S + a[i];
        else K++;
    }
    cout << "Сумма чётных: " << S << endl;
    cout << "Количество нечётных: " << K << endl;
    return 0;
}
```

